#!/usr/bin/env bash
set -euo pipefail
mkdir -p public/media/user
decode_media() {
  local name="$1"
  local expected="$2"
  base64 -d > "public/media/user/$name"
  echo "$expected  public/media/user/$name" | sha256sum -c -
}

decode_media 'food-table.webp' '4a5c4e6ed515d001e62696afc94dd4a58c389f97efe40b45d56bbf349af6bd0e' <<'KOL_MEDIA_EOF'

KOL_MEDIA_EOF

...TRUNCATED_FOR_TOOL_SIZE...
